E=weight('model.language_model.embed_tokens.weight')
fn=weight('model.language_model.norm.weight')
ids={s:tokenize(s)[-1] for s in ['Wait',' Wait','</think>','Final',' answer','boxed','\n']}
for s,id in ids.items(): print(s,id,'embnorm',np.linalg.norm(E[id]), 'emb first', E[id,:3])
vecs={}
for name,(good,bad) in {
    'stop- Wait':('</think>',' Wait'),
    'stop-Wait':('</think>','Wait'),
    'final-Wait':('Final','Wait'),
    'answer-Wait':(' answer','Wait'),
}.items():
    g=E[ids[good]]; b=E[ids[bad]]
    d=fn*(g-b)
    vecs[name]=d
    print(name,'norm',np.linalg.norm(d),'plainnorm',np.linalg.norm(g-b),'dot effects approx raw', {s: float(E[id]@(fn*d/np.sqrt(1024))) for s,id in ids.items()})
# compute for unit norm d effects at probed contexts via exact norm approx: logits before/after adding c*d
p=artifact('probe-002')
for name,d in vecs.items():
    d=d.astype(np.float32)
    print('\n',name)
    for c in [0.5,1,2,4,8]:
        changes=[]
        for t in p['texts'][:8]:
            h=np.array(t['hidden'])[-1,0,:].astype(np.float32)
            def normed(hh): return (hh/np.sqrt(np.mean(hh*hh)+1e-6))*fn
            hn0=normed(h); hn1=normed(h+c*d)
            logit_change=(E[[ids['Wait'],ids[' Wait'],ids['</think>'],ids['Final']]]@(hn1-hn0))
            changes.append(logit_change)
        avg=np.mean(changes,axis=0)
        print('c',c,'avg dlogit Wait,spWait,stop,Final',avg,'norm added',np.linalg.norm(c*d))
